import { createHash } from 'crypto';
import {
  GUIDANCE_SOURCE_BYTES,
  type GuidanceSourceContent,
} from '../types/guidance-source';
import { GUIDANCE_IMAGE_BYTES } from '../types/guidance';
import {
  guidanceImageReferences,
  validateGuidanceImages,
} from './guidanceImages';
import { describeProfileImage } from './profiles/ProfileMedia';
import {
  PROFILE_UPLOAD_BYTES,
  PROFILE_UPLOAD_COUNT,
} from '../types/design-profile';

interface SourceContentInput {
  read: (image?: string) => Promise<Buffer>;
  revision?: string;
}

export const guidanceSourceContent = async ({
  read,
  revision,
}: SourceContentInput): Promise<GuidanceSourceContent> => {
  const bytes = await read();
  if (bytes.length > GUIDANCE_SOURCE_BYTES)
    throw new Error('Source exceeds the 50 MiB upload limit');
  const markdown = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  if (!markdown.trim()) throw new Error('The source must contain Markdown');
  const images: NonNullable<GuidanceSourceContent['images']> = [];
  const sources = new Set(
    guidanceImageReferences(markdown).map((image) => image.source),
  );
  if (sources.size > PROFILE_UPLOAD_COUNT)
    throw new Error('Source images exceed the upload count limit');
  const hashes = new Set<string>();
  let imageBytes = 0;
  for (const source of sources) {
    const image = await read(decodeURIComponent(source));
    if (image.length > GUIDANCE_IMAGE_BYTES)
      throw new Error('Source image exceeds 10 MiB');
    const { mimeType, hash } = describeProfileImage(image);
    if (!hashes.has(hash)) {
      hashes.add(hash);
      imageBytes += image.length;
      if (imageBytes > PROFILE_UPLOAD_BYTES)
        throw new Error('Source images exceed the 35 MiB upload limit');
    }
    images.push({
      source,
      dataUrl: `data:${mimeType};base64,${image.toString('base64')}`,
    });
  }
  const content = { markdown, ...(images.length ? { images } : {}) };
  validateGuidanceImages(content);
  return {
    ...content,
    revision:
      revision ??
      createHash('sha256').update(JSON.stringify(content)).digest('hex'),
  };
};
